def main_solution(n):
    """
    Calculate the number of distinct ways to climb a staircase with n steps,
    where each move can be either 1 or 2 steps.
    """
    memo = {1: 1, 2: 2}

    def helper(x):
        if x not in memo:
            memo[x] = helper(x-1) + helper(x-2)
        return memo[x]

    return helper(n)
