def main_solution(n, W, v, w):
    # Initialize DP table with dimensions n x (W+1)
    dpTable = [[0] * (W + 1) for _ in range(n)]

    # Fill the first row (only first item considered)
    for weight in range(W + 1):
        if weight < w[0]:
            dpTable[0][weight] = 0
        else:
            dpTable[0][weight] = v[0]

    # Fill remaining rows using dynamic programming
    for i in range(1, n):
        for weight in range(W + 1):
            if weight < w[i]:
                dpTable[i][weight] = dpTable[i-1][weight]
            else:
                dpTable[i][weight] = max(
                    dpTable[i-1][weight - w[i]] + v[i],
                    dpTable[i-1][weight]
                )

    # Return maximum value from last row
    return max(dpTable[-1])
