def main_solution(n, m, tracks):
    rows_with_tracks = {}
    for r, c1, c2 in tracks:
        if r not in rows_with_tracks:
            rows_with_tracks[r] = []
        rows_with_tracks[r].append((c1, c2))

    total = n * m

    for tracks_in_row in rows_with_tracks.values():
        # Sort tracks by starting column
        tracks_in_row.sort()
        rightmost = 0

        for c1, c2 in tracks_in_row:
            if c1 > rightmost:
                # No overlap with previous tracks
                total -= (c2 - c1 + 1)
            elif c2 > rightmost:
                # Partial overlap
                total -= (c2 - rightmost)

            # Update rightmost boundary
            if c2 > rightmost:
                rightmost = c2

    return total
```

