            continue
        fields = line.split(',')
        if len(fields) < 8 or not fields[7].isdigit():
            continue
        lng = fields[0]
        lat = fields[1]
        cluster = fields[7]
        geo_infor.append(
            {
                'geometry': {
                    'type': 'Point',
                    'coordinates': [lng, lat]
                },
                'count': weight_dict[cluster]
            })
    return geo_infor
